<span class="line"><span style="color:#C678DD;">    template</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#C678DD;">typename</span><span style="color:#E5C07B;"> T</span><span style="color:#ABB2BF;">&gt;</span></span>
